/**
 * Keep `candidates` whose box sits in `relation` to at least one
 * landmark. Find them however you want (`scoredSearch`, a VLM +
 * [`Machine.nodeAtPoint`], `find`, …). Candidates with no box are
 * omitted from the result. Input order is preserved.
 *
 * Binding for `simulang_rs::search_relative`. `relation` is
 * `(candidate, landmark) => boolean` — compose the
 * [`BoundingBox`] predicates however you want:
 *
 * ```js
 * const buttons = window.scoredSearch(/* … *\/, "I'm Feeling Lucky", 0.75)
 * const fields = window.scoredSearch(/* … *\/, "Google Search", 0.75)
 * searchRelative(buttons, fields, (button, field) =>
 *   button.isBelow(field) && button.overlapsX(field)
 * )
 * ```
 */
export declare function searchRelative(
  candidates: Array<AccessibilityNode>,
  landmarks: Array<AccessibilityNode>,
  relation: (candidate: BoundingBox, landmark: BoundingBox) => boolean,
): Array<AccessibilityNode>

/** Options for [`AccessibilitySnapshot.toStringWith`]. */
export interface SnapshotPrintOptions {
  /**
   * Hoist unnamed structural wrappers out of the output: the wrapper line
   * is skipped and its children are rendered at the depth the wrapper
   * would have had. The root is always rendered. Defaults to `true`.
   */
  collapseStructural?: boolean
  /**
   * Only render interactive elements (buttons, links, inputs, …) and the
   * ancestors needed to give them context: a node is dropped when its
   * role is not interactive **and** no rendered node exists below it.
   * Defaults to `false`.
   */
  interactiveOnly?: boolean
  /**
   * Maximum rendered depth (post-collapse, `0`-based). Nodes deeper than
   * this — and their entire subtrees — are dropped. Unset renders all
   * depths.
   */
  maxDepth?: number
  /**
   * Maximum characters per node name; longer names are cut and suffixed
   * with `…`. Also caps rendered values, which are capped at 80 characters
   * when this is unset.
   */
  maxChars?: number
}

/** Tree traversal order for `AccessibilityTree.find()`. */
export declare enum TraversalOrder {
  /** Pre-order depth-first (each node before its descendants). */
  DepthFirst = 0,
  /** Level-order breadth-first (parents before children). */
  BreadthFirst = 1,
}

/** Visibility behavior when opening an application. */
export declare enum Visibility {
  /** Launch hidden when supported by the platform. */
  Hidden = 0,
  /** Launch in a visible state. */
  Show = 1,
}
